#include <array>
#include <cstddef>
#include <iostream>
#include <string>

bool isAnagram(const std::string& s, const std::string& t) {
    if (s.size() != t.size()) {
        return false;
    }
    std::array<int, 26> counts{};
    for (std::size_t i = 0; i < s.size(); i++) {
        counts[s[i] - 'a']++;
        counts[t[i] - 'a']--;
    }
    for (int count : counts) {
        if (count != 0) {
            return false;
        }
    }
    return true;
}

int main() {
    std::string s, t;
    std::cin >> s >> t;
    std::cout << (isAnagram(s, t) ? "true" : "false") << "\n";
    return 0;
}

